const VERIFIED_SEARCH_COURSES=[{id:'verified-applewood-windham-nh',name:'Applewood Golf Links',aliases:['Applewood Golf Course','Applewood Golf Links and Heavy Hitters Driving Range','Apple Wood'],address:'55 Range Road, Windham, NH 03087, New Hampshire',location:{lat:42.808978,lon:-71.25861,address:'55 Range Road, Windham, NH 03087'},website:'https://www.newhampshiregolf.com/golfcourses/applewood-golf-links',locationSource:'https://www.newhampshiregolf.com/golfcourses/applewood-golf-links',searchDirectoryOnly:true,tees:[]},{id:'verified-la-cana-puntacana',name:'La Cana Golf Club',aliases:['Lacana','Puntacana Resort','La Cana Golf Course'],address:'Punta Cana, La Altagracia, Dominican Republic',location:{lat:18.5194444444,lon:-68.375,address:'Punta Cana, La Altagracia, Dominican Republic'},website:'https://www.puntacana.com/en/golf/la-cana-golf-course',locationSource:'https://dgcine.gob.do/locaciones/en/location/la-cana-golf-club/',searchDirectoryOnly:true,tees:[]}];
const flexibleSearchCache=new Map();
function courseSearchVariants(query){const text=courseSearchText(query),tokens=courseSearchTokens(query);return [...new Set([text,...(tokens.length>1?[tokens[0],tokens.at(-1)]:[]),tokens.length>=3?tokens[0]+tokens[1]:tokens[0]?.length>=5?tokens[0].slice(0,4):''].filter(q=>q&&q.length>=3))].slice(0,4)}
async function flexibleCourseSearch(query){const local=localCourseSearch(query);if(local.length)return local;const batches=await Promise.allSettled(courseSearchVariants(query).map(async q=>{if(flexibleSearchCache.has(q))return flexibleSearchCache.get(q);const pending=(async()=>{const response=await fetch('https://api.opengolfapi.org/v1/courses/search?'+new URLSearchParams({q,limit:'100'}),{signal:AbortSignal.timeout(10000)});if(!response.ok)throw Error('Course search unavailable');const data=await response.json();if(!Array.isArray(data.courses))throw Error('Invalid course search');return data.courses.flatMap(raw=>{try{const c=correctCourseSearchRecord(normalizeCourse(raw));if(raw.id==='eed1bd40-9db9-45f1-a061-fd870f722695'&&/plantationgcc\.com/i.test(raw.website||'')&&/venice/i.test(raw.city||'')){c.name='Plantation Golf & Country Club';c.address='500 Rockley Boulevard, Venice, FL 34293';if(c.location)c.location.address=c.address;c.searchDirectoryOnly=true;c.website='https://www.plantationgcc.com/'}return [c]}catch{return []}})})();flexibleSearchCache.set(q,pending);try{const result=await pending;while(flexibleSearchCache.size>80)flexibleSearchCache.delete(flexibleSearchCache.keys().next().value);return result}catch(e){flexibleSearchCache.delete(q);throw e}}));const unique=new Map(VERIFIED_SEARCH_COURSES.map(c=>[c.id,c]));for(const batch of batches)if(batch.status==='fulfilled')for(const course of batch.value)unique.set(course.id,course);if(batches.length&&batches.every(b=>b.status==='rejected')&&!VERIFIED_SEARCH_COURSES.some(c=>courseMatchScore(c,query)>0))throw Error('Course search unavailable');return [...unique.values()].map(course=>({course,score:courseMatchScore(course,query)})).filter(c=>c.score>0).sort((a,b)=>b.score-a.score||a.course.name.localeCompare(b.course.name)).slice(0,12).map(c=>c.course)}

