let localCourseSearchRecords=null;
const courseStateNames={MA:'Massachusetts',NH:'New Hampshire',FL:'Florida',CA:'California',NY:'New York',TX:'Texas',NC:'North Carolina',SC:'South Carolina',GA:'Georgia',OH:'Ohio',PA:'Pennsylvania',NJ:'New Jersey',CT:'Connecticut',RI:'Rhode Island',VT:'Vermont',ME:'Maine',VA:'Virginia',WA:'Washington',OR:'Oregon',AZ:'Arizona',CO:'Colorado',MI:'Michigan',WI:'Wisconsin',MN:'Minnesota',IL:'Illinois',IN:'Indiana',MO:'Missouri',MD:'Maryland',DE:'Delaware',AL:'Alabama',AK:'Alaska',AR:'Arkansas',HI:'Hawaii',ID:'Idaho',IA:'Iowa',KS:'Kansas',KY:'Kentucky',LA:'Louisiana',MS:'Mississippi',MT:'Montana',NE:'Nebraska',NV:'Nevada',NM:'New Mexico',ND:'North Dakota',OK:'Oklahoma',SD:'South Dakota',TN:'Tennessee',UT:'Utah',WV:'West Virginia',WY:'Wyoming'};
function correctCourseSearchRecord(c){if(c.id==='eb47bf0f-e5db-426a-a389-79f58a8432ea'&&c.location&&Math.abs(c.location.lat-42.669483)<.01&&Math.abs(c.location.lon+71.721578)<.01){c.name='Northern Spy Golf Club';c.aliases=['Townsend Ridge Country Club','Northern Spy Country Club'];c.address='40 Scales Lane, Townsend, MA 01469, Massachusetts';c.location.address=c.address;c.website='https://northernspygc.com/';c.searchDirectoryOnly=true}if(c.id==='eed1bd40-9db9-45f1-a061-fd870f722695'&&c.location&&Math.abs(c.location.lat-27.0604345)<.01&&Math.abs(c.location.lon+82.358504)<.01){c.name='Plantation Golf & Country Club';c.address='500 Rockley Boulevard, Venice, FL 34293';c.location.address=c.address;c.website='https://www.plantationgcc.com/';c.searchDirectoryOnly=true}return c}
function localCourseSearch(query){if(!localCourseSearchRecords)localCourseSearchRecords=LOCAL_COURSE_SEARCH_INDEX.map(([id,name,city,state,lat,lon,street,zip])=>{const streetWords=courseSearchText(street).split(/\s+/),address=[street,city&&!courseSearchText(street).includes(courseSearchText(city))?city:'',state&&!streetWords.includes(state.toLowerCase())?state:'',zip&&!streetWords.includes(zip)?zip:''].filter(Boolean).join(', ');return correctCourseSearchRecord({id,name,address,city,region:courseStateNames[state],country:'United States',aliases:[state,zip],location:{lat,lon,address},tees:[],source:'OpenGolfAPI'})});return [...VERIFIED_SEARCH_COURSES,...localCourseSearchRecords].map(course=>({course,score:courseMatchScore(course,query)})).filter(c=>c.score>0).sort((a,b)=>b.score-a.score||a.course.name.localeCompare(b.course.name)).slice(0,12).map(c=>c.course)}

const preparedCourseSearchCache=new WeakMap();
function preparedCourseSearch(course){let prepared=preparedCourseSearchCache.get(course);if(!prepared){const name=courseSearchText(course.name||course.course),location=courseSearchText([course.address,course.city,course.region,course.country,course.location?.address,course.location?.city,...(course.aliases||[])].filter(Boolean).join(' '));prepared={name,words:[...new Set((name+' '+location).split(/\s+/))]};preparedCourseSearchCache.set(course,prepared)}return prepared}

// Annual recaps use recorded data only. Unknown is different from zero.
let seasonSpotlight=0;
function validRoundExtras(e){return !!e&&typeof e==='object'&&!Array.isArray(e)&&['outOfBounds','waterBalls','penaltyStrokes','minutes'].every(k=>e[k]===undefined||e[k]===null||Number.isInteger(e[k])&&e[k]>=0&&e[k]<=(k==='minutes'?1440:99))}
function roundExtrasEditor(r){return `<details class="round-extra"><summary>A little more about your round (optional)</summary><p class="feature-caption">Leave a field blank if you didn’t track it. Enter 0 for none. Penalty strokes should already be included in your total score.</p><div class="form-grid">${[['outOfBounds','Balls out of bounds'],['waterBalls','Balls into water'],['penaltyStrokes','Penalty strokes'],['minutes','Time played (minutes)']].map(([key,label])=>`<label>${label}<input name="extra-${key}" type="number" min="0" max="${key==='minutes'?1440:99}" step="1" value="${r.extras?.[key]??''}" placeholder="Not tracked"></label>`).join('')}</div></details>`}
function seasonRoundHoles(r){if(!r.courseCard||!validCourseCard(r.courseCard))return [];let holes=[...r.courseCard.tee.holes].sort((a,b)=>a.number-b.number);if(r.holes===9&&(r.courseCard.courseHoles===18||holes.some(h=>h.number>9)))holes=holes.filter(h=>r.courseNine==='back'?h.number>9:h.number<=9);return holes.slice(0,r.holes).map(h=>{const index=r.holes===9?h.number-(r.courseNine==='back'?10:1):h.number-1;return {...h,round:r,score:!r.scoreNotKept&&Number.isInteger(r.scores?.[index])?r.scores[index]:null}})}
function annualStats(records,year){
 const rounds=records.filter(r=>!r.sample&&(!year||r.date.slice(0,4)===String(year))),best=n=>[...rounds].filter(r=>r.holes===n&&Number.isFinite(r.score)).sort((a,b)=>a.score-b.score||a.date.localeCompare(b.date))[0]||null;
 const holes=rounds.flatMap(seasonRoundHoles),measured=holes.filter(h=>Number.isFinite(h.yards)),scored=holes.filter(h=>Number.isFinite(h.par)&&Number.isInteger(h.score)),buckets={eagle:[],birdie:[],par:[],bogey:[],double:[]};
 for(const h of scored){const d=h.score-h.par;buckets[d<=-2?'eagle':d===-1?'birdie':d===0?'par':d===1?'bogey':'double'].push(h)}
 const reported=key=>{const known=rounds.filter(r=>validRoundExtras(r.extras)&&Number.isInteger(r.extras[key]));return {total:known.length?known.reduce((n,r)=>n+r.extras[key],0):null,known:known.length,rounds:known}};
 let streak=null;for(const r of rounds){let run=[];for(const h of seasonRoundHoles(r)){if(h.score!==null&&h.par!==null&&h.score<=h.par&&(!run.length||h.number===run.at(-1).number+1))run.push(h);else run=h.score!==null&&h.par!==null&&h.score<=h.par?[h]:[];if(run.length>(streak?.length||0))streak={length:run.length,first:run[0],last:h}}}
 const average=n=>{const eligible=rounds.filter(r=>r.holes===n&&Number.isFinite(r.score));return eligible.length?Math.round(eligible.reduce((sum,r)=>sum+r.score,0)/eligible.length*10)/10:null};
 const puttRounds=rounds.filter(r=>Number.isInteger(r.putts)),courses=bookCourses(rounds).sort((a,b)=>b.rounds.length-a.rounds.length||a.name.localeCompare(b.name));
 return {rounds,average18:average(18),average9:average(9),strokes:rounds.reduce((n,r)=>n+(r.score??0),0),holesPlayed:rounds.reduce((n,r)=>n+r.holes,0),best18:best(18),best9:best(9),holes,measured,scored,buckets,streak,longest:[...measured].sort((a,b)=>b.yards-a.yards)[0]||null,shortest:[...measured].sort((a,b)=>a.yards-b.yards)[0]||null,putts:{total:puttRounds.length?puttRounds.reduce((n,r)=>n+r.putts,0):null,known:puttRounds.length,rounds:puttRounds},outOfBounds:reported('outOfBounds'),waterBalls:reported('waterBalls'),penaltyStrokes:reported('penaltyStrokes'),minutes:reported('minutes'),days:new Set(rounds.map(r=>r.date)).size,courses,months:Array.from({length:12},(_,i)=>rounds.filter(r=>+r.date.slice(5,7)===i+1))};
}
function seasonYears(){return [...new Set([String(new Date().getFullYear()),...state.rounds.filter(r=>!r.sample).map(r=>r.date.slice(0,4)),...state.notes.map(n=>n.date.slice(0,4))])].sort().reverse()}
function seasonHeader(section){return `<div class="book-heading"><div><span class="eyebrow">The score is only half the story</span><h1>Your statistics.</h1><p class="muted">Your scores, records, and time on the course.</p></div><label class="book-year">Show<select onchange="setBookYear(this.value)"><option value="" ${bookYear===''?'selected':''}>All time</option>${seasonYears().map(y=>`<option ${bookYear===y?'selected':''}>${y}</option>`).join('')}</select></label></div><div class="book-segments" role="group" aria-label="Yardage Book views">${[['stats','Statistics'],['map','Places'],['memories','Memories']].map(([key,label])=>`<button class="${section===key?'selected':''}" aria-pressed="${section===key}" onclick="selectBookSection('${key}')">${label}</button>`).join('')}</div>`}
function seasonRef(r,h){return `${esc(r.course)}${h?' · Hole '+h.number:''}<br>${esc(r.tees)} tees · ${esc(r.date)}`}
function seasonHighlights(s){const options=[];for(const [key,r,length] of [['best18',s.best18,18],['best9',s.best9,9]])if(r)options.push({key,label:'Your best '+length+'-hole round',value:r.score,unit:'strokes',ref:seasonRef(r),copy:'One for the memory bank.'});for(const [key,h,label] of [['longest',s.longest,'The long way home'],['shortest',s.shortest,'Small hole. Big memories.']])if(h)options.push({key,label,value:h.yards,unit:'yard '+(key==='longest'?'longest':'shortest')+' recorded hole',ref:seasonRef(h.round,h),copy:'From the tee card saved with your round.'});if(s.streak)options.push({key:'streak',label:'You found your rhythm',value:s.streak.length,unit:'consecutive holes at par or better',ref:seasonRef(s.streak.first.round)+'<br>Holes '+s.streak.first.number+'–'+s.streak.last.number,copy:'Your best run within a single round.'});if(!options.length)options.push({key:'strokes',label:'Your story starts on the first tee',value:s.strokes,unit:'strokes recorded',ref:'Log a round to start collecting your highlights.',copy:'Every round adds a new chapter.'});return options}
function seasonSpotlightHtml(s){const options=seasonHighlights(s),item=options[seasonSpotlight%options.length];return `<span class="eyebrow">${item.label}</span><button class="spotlight-number" onclick="seasonDetail('${item.key}')"><strong>${item.value.toLocaleString()}</strong><span>${item.unit}</span></button><p class="spotlight-ref">${item.ref}</p><div class="spotlight-bottom"><small>${item.copy}</small><button class="text" onclick="nextSeasonHighlight()">Another highlight ${golfMark('arrow')}</button></div>`}
function nextSeasonHighlight(){seasonSpotlight++;const el=document.querySelector('#season-spotlight');if(el){el.innerHTML=seasonSpotlightHtml(annualStats(state.rounds,bookYear));if(!matchMedia('(prefers-reduced-motion: reduce)').matches)el.animate?.([{opacity:.35,transform:'translateX(10px)'},{opacity:1,transform:'translateX(0)'}],{duration:220})}}
function seasonMetric(key,value,label,caption=''){return `<button class="season-metric" onclick="seasonDetail('${key}')"><strong>${value===null?'—':value.toLocaleString()}</strong><span>${label}</span><small>${caption||'Tap to see the rounds'}</small></button>`}
function annualBook(){const s=annualStats(state.rounds,bookYear),coverage=v=>v.known+' of '+s.rounds.length+' rounds tracked',max=Math.max(1,...s.months.map(m=>m.length)),labels=['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'];return `<div class="yardage-book annual-book">${seasonHeader('stats')}<section class="season-opening"><div><span class="eyebrow">Every swing counts</span><button class="season-stroke-total ${s.strokes>=10000?'is-large':''}" onclick="seasonDetail('strokes')"><strong>${s.strokes.toLocaleString()}</strong><span>total strokes ${bookYear?'in '+esc(bookYear):'across all years'} ${golfMark('arrow')}</span></button><p class="season-opening-meta">${s.rounds.length} rounds · ${s.holesPlayed} holes · ${s.days} days on the course</p></div><button class="season-map-link" onclick="selectBookSection('map')">${golfMark('pin')}<strong>${s.courses.length}</strong><span>courses explored</span><small>Explore your places →</small></button></section><section class="season-spotlight" id="season-spotlight">${seasonSpotlightHtml(s)}</section><div class="season-section-heading"><div><h2>The ones you’ll talk about.</h2><p class="muted">Tap any record to revisit the round.</p></div></div><div class="season-records">${seasonMetric('average18',s.average18,'18-hole scoring average','Only 18-hole rounds')}${seasonMetric('average9',s.average9,'Nine-hole scoring average','Only nine-hole rounds')}${seasonMetric('best18',s.best18?.score??null,'Best 18-hole round',s.best18?esc(s.best18.course):'Your next round could be the one')}${seasonMetric('best9',s.best9?.score??null,'Best nine-hole round',s.best9?esc(s.best9.course):'Nine-hole rounds stay separate')}${seasonMetric('longest',s.longest?.yards??null,'Longest recorded hole',s.longest?esc(s.longest.round.course)+' · Hole '+s.longest.number:'Select a course + tees when logging')}${seasonMetric('shortest',s.shortest?.yards??null,'Shortest recorded hole',s.shortest?esc(s.shortest.round.course)+' · Hole '+s.shortest.number:'Saved tee yardages unlock this')}</div><p class="feature-caption">Hole records use ${s.measured.length} of ${s.holesPlayed} played holes with saved yardages. These are hole lengths, not shot distances. <a href="https://opengolfapi.org/attribution/" target="_blank" rel="noopener">© OpenStreetMap contributors via OpenGolfAPI</a>.</p><section class="season-activity"><h2>When golf happened.</h2><p class="muted">${bookYear?'Tap a month to replay its rounds.':'Rounds by calendar month across all years. Tap to explore.'}</p><div class="season-months">${s.months.map((rounds,i)=>`<button onclick="seasonMonth(${i})" aria-label="${labels[i]} ${bookYear||'All time'}: ${rounds.length} rounds"><span class="month-count">${rounds.length||''}</span><i style="height:${Math.max(4,rounds.length/max*92)}px"></i><small>${labels[i]}</small></button>`).join('')}</div></section><section class="season-score-story"><h2>A few reasons to come back.</h2><p class="muted">From ${s.scored.length} holes with both a saved par and a hole score.</p><div class="season-score-chips">${[['eagle','Eagle or better'],['birdie','Birdies'],['par','Pars'],['bogey','Bogeys'],['double','Double bogey+']].map(([key,label])=>`<button onclick="seasonDetail('${key}')"><strong>${s.scored.length?s.buckets[key].length:'—'}</strong><span>${label}</span></button>`).join('')}</div>${s.streak?`<button class="season-streak" onclick="seasonDetail('streak')">${golfMark('spark')}<span><strong>${s.streak.length} holes in a groove</strong><small>Your best in-round run at par or better →</small></span></button>`:'<p class="feature-caption">Hole-by-hole scores unlock your par-or-better streaks.</p>'}</section><section><h2>The whole story.</h2><p class="muted">The good, the wet, and the ones over the fence.</p><div class="season-records">${seasonMetric('putts',s.putts.total,'Putts recorded',coverage(s.putts))}${seasonMetric('outOfBounds',s.outOfBounds.total,'Balls out of bounds',coverage(s.outOfBounds))}${seasonMetric('waterBalls',s.waterBalls.total,'Balls into water',coverage(s.waterBalls))}${seasonMetric('penaltyStrokes',s.penaltyStrokes.total,'Penalty strokes',coverage(s.penaltyStrokes))}${seasonMetric('minutes',s.minutes.total===null?null:Math.round(s.minutes.total/60*10)/10,'Hours on the course',coverage(s.minutes))}${seasonMetric('favourite',s.courses[0]?.rounds.length??null,'Visits to your most-played course',s.courses[0]?esc(s.courses[0].name):'Your regular spot will appear here')}</div><p class="feature-caption">A dash means not tracked. Penalties are already part of total strokes and are not added again.</p></section><div class="season-finish"><p>${s.rounds.length?'Same game. A different story every round.':'Your first round starts the story.'}</p><button onclick="roundForm()">Log a round</button><button class="text" onclick="seasonRecap()">Open my recap</button></div></div>`}
function seasonRoundList(rounds){return rounds.map(r=>`<button class="season-receipt" onclick="roundForm('${r.id}')"><span><strong>${esc(r.course)}</strong><small>${esc(r.date)} · ${r.holes} holes · ${esc(r.tees)} tees</small></span><strong>${r.score??'Score not kept'}</strong>${golfMark('arrow')}</button>`).join('')||'<p class="muted">No rounds recorded for this stat yet.</p>'}
function seasonHoleList(holes){return holes.slice(0,60).map(h=>`<button class="season-receipt" onclick="roundForm('${h.round.id}')"><span><strong>${esc(h.round.course)} · Hole ${h.number}</strong><small>${esc(h.round.date)} · ${esc(h.round.tees)} tees · ${h.yards??'—'} yd · Par ${h.par??'—'}${h.score!==null?' · '+h.score+' strokes':''}</small></span>${golfMark('arrow')}</button>`).join('')+(holes.length>60?'<p class="feature-caption">Showing the first 60 of '+holes.length+' recorded holes.</p>':'')}
function seasonDetail(key){const s=annualStats(state.rounds,bookYear),titles={average18:'18-hole scoring average',average9:'Nine-hole scoring average',strokes:'Every swing counts',best18:'Best 18-hole round',best9:'Best nine-hole round',longest:'Longest recorded hole',shortest:'Shortest recorded hole',streak:'Your best in-round streak',putts:'Putts recorded',outOfBounds:'Balls out of bounds',waterBalls:'Balls into water',penaltyStrokes:'Penalty strokes',minutes:'Time on the course',favourite:'Your most-played course',eagle:'Eagle or better',birdie:'Birdies',par:'Pars',bogey:'Bogeys',double:'Double bogey or worse'};if(!titles[key])return;let body='';if(key==='average18'||key==='average9')body='<p>Average: '+(s[key]??'—')+' strokes. Round lengths are calculated separately.</p>'+seasonRoundList(s.rounds.filter(r=>r.holes===(key==='average18'?18:9)&&Number.isFinite(r.score)));else if(['longest','shortest'].includes(key))body=s[key]?seasonHoleList([s[key]]):'<p>Select a course and tees when logging to record hole yardages.</p>';else if(s.buckets[key])body=s.buckets[key].length?seasonHoleList(s.buckets[key]):'<p>No matching scored holes yet. Add hole scores and a course card to track this.</p>';else if(key==='streak')body=s.streak?`<p>${s.streak.length} consecutive holes at par or better. Holes ${s.streak.first.number}–${s.streak.last.number}.</p>`+seasonHoleList([s.streak.first]):'<p>Hole scores with saved pars unlock this record.</p>';else if(key==='best18'||key==='best9')body=seasonRoundList(s[key]?[s[key]]:[]);else if(key==='favourite')body=seasonRoundList(s.courses[0]?.rounds||[]);else if(key==='strokes')body=seasonRoundList(s.rounds);else{const m=s[key];body=`<p class="feature-caption">${m.known} of ${s.rounds.length} rounds tracked. Unknown rounds are excluded.</p>`+m.rounds.map(r=>`<button class="season-receipt" onclick="roundForm('${r.id}')"><span><strong>${esc(r.course)}</strong><small>${esc(r.date)}</small></span><strong>${key==='putts'?r.putts:r.extras[key]}${key==='minutes'?' min':''}</strong></button>`).join('');if(!m.known)body+='<p>Add this optional detail when logging or editing a round. Leave blank for unknown; enter 0 for none.</p>'+seasonRoundList(s.rounds.slice(-5))}openModal(titles[key]+' · '+esc(bookYear||'All time'),body)}
function seasonMonth(index){const s=annualStats(state.rounds,bookYear),month=new Date(2000,index,1).toLocaleString('en',{month:'long'});openModal(esc(month)+' '+esc(bookYear||'All time'),seasonRoundList(s.months[index]||[]))}
function seasonRecap(){const s=annualStats(state.rounds,bookYear);openModal('Your '+esc(bookYear||'All time')+' recap',`<div class="year-recap"><span class="eyebrow">DOGLEG · A life well played</span><h2>${esc(state.profile.name)}’s ${esc(bookYear||'All time')}</h2><strong>${s.strokes.toLocaleString()}</strong><p>strokes · ${s.rounds.length} rounds · ${s.courses.length} courses</p><p>Best 18: ${s.best18?.score??'—'} · Best nine: ${s.best9?.score??'—'}</p><p>Birdies: ${s.scored.length?s.buckets.birdie.length:'—'} from ${s.scored.length} scored holes with par.</p><p>OB balls recorded: ${s.outOfBounds.total??'—'} (${s.outOfBounds.known} rounds tracked)</p><small>Only recorded data for the selected period.</small></div><button class="section-gap" onclick="downloadYearRecap()">Download recap</button><p id="year-recap-status" class="feature-caption" role="status"></p><img id="year-recap-preview" hidden alt="Your annual Dogleg recap" style="width:100%;height:auto;margin-top:16px;border-radius:16px">`)}
function downloadYearRecap(){try{const s=annualStats(state.rounds,bookYear),canvas=document.createElement('canvas');canvas.width=1080;canvas.height=1350;const ctx=canvas.getContext('2d');ctx.fillStyle='#174b3b';ctx.fillRect(0,0,1080,1350);ctx.fillStyle='#f6f7dd';const write=(text,x,y,size=28,weight=400)=>{ctx.font=weight+' '+size+'px "Source Sans 3",sans-serif';ctx.fillText(String(text),x,y,940)};write('DOGLEG  /  A LIFE WELL PLAYED',70,90,24,600);write(state.profile.name+'’s '+(bookYear||'All time'),70,175,52,600);write(s.strokes.toLocaleString(),65,385,s.strokes>=10000?135:170,700);write('TOTAL STROKES',75,440,25,600);write(s.rounds.length+' rounds  ·  '+s.courses.length+' courses  ·  '+s.holesPlayed+' holes',70,510,32);ctx.fillStyle='#9fc19a';ctx.fillRect(70,555,940,2);ctx.fillStyle='#f6f7dd';write('BEST 18',70,625,22,600);write(s.best18?.score??'—',70,705,64,700);write('BEST NINE',560,625,22,600);write(s.best9?.score??'—',560,705,64,700);write('BIRDIES',70,800,22,600);write(s.scored.length?s.buckets.birdie.length:'—',70,875,56,700);write('From '+s.scored.length+' holes with score + par',70,920,22);write('BALLS OUT OF BOUNDS',560,800,22,600);write(s.outOfBounds.total??'—',560,875,56,700);write(s.outOfBounds.known+' of '+s.rounds.length+' rounds tracked',560,920,22);write('LONGEST RECORDED HOLE',70,1015,22,600);write(s.longest?s.longest.yards+' yd  ·  Hole '+s.longest.number:'Not recorded yet',70,1070,35,600);if(s.longest){write(s.longest.round.course,70,1120,28);write(s.longest.round.tees+' tees  ·  '+s.longest.round.date,70,1160,24)}write('Only recorded data for the selected period. A dash means not tracked.',70,1240,21);write('Course data: OpenStreetMap contributors / OpenGolfAPI · ODbL 1.0',70,1280,19);const url=canvas.toDataURL('image/png'),preview=document.querySelector('#year-recap-preview');preview.src=url;preview.hidden=false;const link=document.createElement('a');link.href=url;link.download='dogleg-'+(bookYear||'all-time')+'-recap.png';link.click();document.querySelector('#year-recap-status').textContent='Your recap is ready. Save the preview if your browser didn’t download it.'}catch{const status=document.querySelector('#year-recap-status');if(status)status.textContent='Could not create the image. You can still save a screenshot of your recap.'}}
const seasonBaseBook=views.Passport;views.Passport=()=>bookSection==='stats'?annualBook():seasonBaseBook();
const seasonReadRound=readRound;readRound=function(){const r=seasonReadRound(),form=document.querySelector('#round-form'),extras={};for(const key of ['outOfBounds','waterBalls','penaltyStrokes','minutes']){const value=form.querySelector('[name=extra-'+key+']')?.value;extras[key]=value===undefined||value===''?null:Number(value)}if(Object.values(extras).some(v=>v!==null))r.extras=extras;return r};

