function courseBrandName(value){return String(value||'').normalize('NFKD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/&/g,' and ').replace(/[^\p{L}\p{N}]+/gu,' ').trim()}
function courseBrand(c){const name=courseBrandName(c?.course||c?.name||c||''),id=c?.courseCard?.courseId||c?.courseId||c?.id,location=c?.location||(Number.isFinite(c?.lat)&&Number.isFinite(c?.lon)?c:null),exact=courseBrands.find(b=>b.ids?.includes(id));if(exact)return exact;const candidates=courseBrands.filter(b=>b.names.some(n=>courseBrandName(n)===name)&&(!b.requireLocation||location)&&(!location||Math.abs(location.lat-b.lat)<.1&&Math.abs(location.lon-b.lon)<.1));return candidates.length===1?candidates[0]:undefined}
function courseLogoId(c){const id=c?.courseCard?.courseId||c?.courseId||c?.rounds?.find(r=>r.courseCard?.courseId)?.courseCard.courseId||(!c?.course?c?.id:null);return typeof id==='string'&&/^[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}$/i.test(id)?id:null}
function courseBadge(c){const brand=courseBrand(c);return brand?`<img class="course-logo ${brand.dark?'course-logo-dark':''} ${brand.compact?'course-logo-compact':''}" src="${brand.image}" alt="" decoding="async">`:typeof discoveredLogoMarkup==='function'?discoveredLogoMarkup(c):`<span class="course-monogram" aria-hidden="true">${esc(String(c?.course||c?.name||c||'?').split(/\s+/).filter(Boolean).slice(0,2).map(w=>w[0]).join('').toUpperCase())}</span>`}

// Places is an explorable collection, with click/touch controls rather than hover cards.
let atlasMapYear='',atlasMarkers=null,atlasSelectionOwner=null,atlasSelectionYear='',atlasSelectionKey='',atlasTileFailures=0,atlasStreet=null,atlasImagery=null;

function syncAtlasImagery(){if(!bookMap||!atlasImagery||!atlasStreet)return;const close=bookMap.getZoom()>=14;if(close){if(!bookMap.hasLayer(atlasImagery))atlasImagery.addTo(bookMap);if(bookMap.hasLayer(atlasStreet))bookMap.removeLayer(atlasStreet)}else{if(!bookMap.hasLayer(atlasStreet))atlasStreet.addTo(bookMap);if(bookMap.hasLayer(atlasImagery))bookMap.removeLayer(atlasImagery)}}
function clearAtlasSelection(){const detail=document.querySelector('#book-detail'),hadFocus=detail?.contains?.(document.activeElement);atlasSelectionKey='';bookSelected=-1;if(detail){detail.hidden=true;detail.innerHTML=''}document.querySelectorAll('.atlas-course').forEach(button=>{button.classList.remove('selected');button.setAttribute('aria-pressed','false')});const position=document.querySelector('#atlas-position');if(position)position.textContent='Tap a course dot to explore. Tap the map to return to the overview.';drawAtlasMarkers();if(hadFocus)document.querySelector('#journey-map')?.focus?.({preventScroll:true})}
if(typeof go==='function'){const atlasNavigate=go;go=function(target){if(target==='Passport'&&tab!=='Passport'){atlasSelectionKey='';bookSelected=-1}return atlasNavigate(target)}}
if(typeof selectBookSection==='function'){const atlasSection=selectBookSection;selectBookSection=function(section){if(section==='map'&&bookSection!=='map'){atlasSelectionKey='';bookSelected=-1}return atlasSection(section)}}

function setAtlasYear(value){atlasMapYear=value;bookSelected=-1;render();animateBookChange()}
function atlasCourses(){return bookCourses(bookRecords())}
function atlasSelection(){const courses=atlasCourses();if(atlasSelectionOwner!==state||atlasSelectionYear!==atlasMapYear){atlasSelectionOwner=state;atlasSelectionYear=atlasMapYear;atlasSelectionKey=''}bookSelected=atlasSelectionKey?courses.findIndex(c=>c.name===atlasSelectionKey):-1;if(bookSelected<0)atlasSelectionKey='';return courses}
function clusterMapCourses(courses,project){const byLocation=new Map();courses.forEach((c,index)=>{if(!c.location)return;const p=project(c.location);if(!Number.isFinite(p.x)||!Number.isFinite(p.y))return;const key=c.location.lat+','+c.location.lon;let group=byLocation.get(key);if(!group){group={x:p.x,y:p.y,indices:[]};byLocation.set(key,group)}group.indices.push(index)});return [...byLocation.values()]}
function atlasCourseDetail(){const c=atlasCourses()[bookSelected];if(!c)return '';const full=c.rounds.filter(r=>r.holes===18&&Number.isFinite(r.score)),nine=c.rounds.filter(r=>r.holes===9&&Number.isFinite(r.score)),latest=[...c.rounds].sort((a,b)=>b.date.localeCompare(a.date))[0],photo=c.rounds.flatMap(r=>r.photos||[])[0];return `<button class="text small atlas-detail-close" onclick="clearAtlasSelection()" aria-label="Close course details">×</button><div class="atlas-detail-top"><div><span class="eyebrow">${c.rounds.length} ${c.rounds.length===1?'round':'rounds'} · ${esc(atlasMapYear||'all-time')}</span><h2><span class="course-inline-badge">${courseBadge(c)}</span>${esc(c.name)}</h2></div>${photo?`<img src="${photo}" alt="Your round at ${esc(c.name)}">`:''}</div><p class="atlas-location">${c.location?esc(c.location.address||'Course location saved'):'Not on your map yet. Choose its location to add a dot.'}</p><div class="atlas-facts">${full.length?`<span><strong>${Math.min(...full.map(r=>r.score))}</strong> best 18</span>`:''}${nine.length?`<span><strong>${Math.min(...nine.map(r=>r.score))}</strong> best nine</span>`:''}<span><strong>${latest.score??'—'}</strong> last score</span></div><div class="atlas-detail-actions">${c.location?'<button onclick="bookRoundHistory()">View rounds</button>':'<button onclick="placeBookCourse()">Place on map</button>'}<button class="secondary" onclick="logBookCourse()">Log here</button></div><button class="text small hub-map-link" onclick="openBookCoursePage()">Explore this course →</button><small class="atlas-last-played">Last played ${esc(latest.date)}</small>`}
function atlasCourseStrip(courses){return `<div class="atlas-strip" aria-label="Your course collection">${courses.map((c,i)=>{const full=c.rounds.filter(r=>r.holes===18&&Number.isFinite(r.score)),photo=c.rounds.flatMap(r=>r.photos||[])[0];return `<button class="atlas-course ${i===bookSelected?'selected':''}" aria-pressed="${i===bookSelected}" onclick="selectBookCourse(${i},true)"><span class="atlas-course-art">${courseBrand(c)?courseBadge(c):photo?`<img src="${photo}" alt="">`:courseBadge(c)}</span><span class="atlas-course-copy"><strong>${esc(c.name)}</strong><small>${c.rounds.length} ${c.rounds.length===1?'round':'rounds'}${full.length?' · Best 18: '+Math.min(...full.map(r=>r.score)):''}</small><small>${c.location?'Explore this place →':'Place on map →'}</small></span></button>`}).join('')}</div>`}
function atlasHeader(){return `<div class="book-heading"><div><span class="eyebrow">Yardage Book · Every course has a story</span><h1>Your golf world.</h1></div><label class="book-year">Show<select onchange="setAtlasYear(this.value)"><option value="" ${atlasMapYear===''?'selected':''}>All years</option>${seasonYears().map(y=>`<option ${atlasMapYear===y?'selected':''}>${y}</option>`).join('')}</select></label></div><div class="book-segments" role="group" aria-label="Yardage Book views">${[['stats','Statistics'],['map','Places'],['memories','Memories']].map(([key,label])=>`<button class="${key==='map'?'selected':''}" aria-pressed="${key==='map'}" onclick="selectBookSection('${key}')">${label}</button>`).join('')}</div>`}
function atlasView(){const courses=atlasSelection(),mapped=courses.filter(c=>c.location).length,rounds=bookRecords();return `<div class="yardage-book atlas-book">${atlasHeader()}<div class="atlas-intro"><div><p>${courses.length} courses · ${rounds.length} rounds · ${mapped} mapped on your ${esc(atlasMapYear||'all-time')} map</p></div><button class="text" onclick="clubSearch()">Find your next course ${golfMark('arrow')}</button></div><section class="atlas-stage" aria-label="Interactive course collection"><div id="journey-map" role="region" aria-label="Map of courses you have played"><div class="map-message">Opening your golf world…</div></div><div class="atlas-tools"><button onclick="fitBookMap()">${golfMark('pin')}All places</button><button onclick="toggleAtlasSize()" id="atlas-expand" aria-expanded="false">Expand map</button></div>${mapped>1?`<div class="atlas-map-nav"><button class="secondary" onclick="stepAtlas(-1)" aria-label="Previous mapped course">←</button><button class="secondary" onclick="stepAtlas(1)" aria-label="Next mapped course">Next place →</button><button class="secondary" onclick="surpriseAtlas()">Surprise me</button></div>`:""}<div id="atlas-map-status" class="atlas-map-status" role="status" hidden></div><section class="atlas-detail" id="book-detail" aria-label="Selected course" aria-live="polite" ${bookSelected<0?'hidden':''}>${atlasCourseDetail()}</section></section><div class="atlas-browser"><span id="atlas-position">${mapped?'Each dot marks a place you’ve played. Tap to explore.':'Pan around. Your saved courses will become dots here.'}</span></div>${atlasCourseStrip(courses)}${courses.length>mapped?`<p class="atlas-unplaced">${courses.length-mapped} ${courses.length-mapped===1?'course is':'courses are'} waiting for a dot. Choose an unplaced course, then tap Place on map.</p>`:''}<p class="feature-caption">Course locations come from your saved rounds. Cartography and satellite imagery: © Esri and contributors. Satellite appears at zoom 14. Pinch to zoom on mobile; use +/− or a mouse wheel over a focused map on desktop.</p></div>`}
function atlasBadgeSize(zoom){return 12}
function atlasMarkerHtml(group,courses,zoom){const selected=group.indices.includes(bookSelected),size=atlasBadgeSize(zoom),members=group.indices.map(i=>courses[i]),visits=members.reduce((n,c)=>n+c.rounds.length,0),c=members.find((_,i)=>group.indices[i]===bookSelected)||members[0];return `<div class="atlas-flag atlas-frequency-marker is-dot ${selected?'is-selected':''}" style="--badge-size:${size}px"><span class="atlas-flag-face"></span><span class="atlas-marker-label ${selected?'is-visible':''}">${esc(c.name)} · ${visits} ${visits===1?'round':'rounds'}${members.length>1?' · '+members.length+' courses in this area':''}</span></div>`}
function drawAtlasMarkers(){if(!bookMap||!window.L||!atlasMarkers)return;const active=document.activeElement,focusLabel=active?.classList.contains('atlas-map-marker')?active.getAttribute('aria-label'):null;atlasMarkers.clearLayers();const courses=atlasCourses(),zoom=bookMap.getZoom(),groups=clusterMapCourses(courses,l=>bookMap.project([l.lat,l.lon],zoom));for(const group of groups){const members=group.indices.map(i=>courses[i]),lat=members.reduce((n,c)=>n+c.location.lat,0)/members.length,lon=members.reduce((n,c)=>n+c.location.lon,0)/members.length,multiple=members.length>1,selected=group.indices.includes(bookSelected),marker=window.L.marker([lat,lon],{keyboard:true,bubblingMouseEvents:false,zIndexOffset:selected?1000:0,icon:window.L.divIcon({className:'atlas-map-marker',html:atlasMarkerHtml(group,courses,zoom),iconSize:[24,24],iconAnchor:[12,12]})}).addTo(atlasMarkers);marker.on('click',()=>{if(!multiple){if(bookSelected===group.indices[0])return clearAtlasSelection();return selectBookCourse(group.indices[0])}const allSame=members.every(c=>Math.abs(c.location.lat-lat)<.0001&&Math.abs(c.location.lon-lon)<.0001);if(zoom>=14||allSame)return openAtlasGroup(group.indices);bookMap.fitBounds(members.map(c=>[c.location.lat,c.location.lon]),{padding:[80,80],maxZoom:15,animate:atlasMotion()})});const element=marker.getElement();element?.setAttribute('aria-label',multiple?'Explore '+members.length+' courses in this area':'Explore '+courses[group.indices[0]].name);element?.setAttribute('aria-pressed',String(selected))}if(focusLabel&&!modal.open){const markers=[...document.querySelectorAll('.atlas-map-marker')];(markers.find(m=>m.getAttribute('aria-label')===focusLabel)||markers.find(m=>m.getAttribute('aria-pressed')==='true'))?.focus({preventScroll:true})}}
function atlasMotion(){return !matchMedia('(prefers-reduced-motion: reduce)').matches}
function openAtlasGroup(indices){const courses=atlasCourses();openModal('Choose a course in this area',indices.map(i=>`<button class="season-receipt" onclick="chooseAtlasGroupCourse(${i})"><span><strong>${esc(courses[i].name)}</strong><small>${courses[i].rounds.length} ${courses[i].rounds.length===1?'round':'rounds'} · ${esc(courses[i].location.address||'Shared course area')}</small></span>${golfMark('arrow')}</button>`).join(''))}
function chooseAtlasGroupCourse(i){modal.close();selectBookCourse(i,true)}
selectBookCourse=function(i,scrollStrip=false){const courses=atlasCourses(),c=courses[i];if(!c)return;bookSelected=i;atlasSelectionKey=c.name;const detail=document.querySelector('#book-detail');if(detail){detail.hidden=false;detail.innerHTML=atlasCourseDetail();if(atlasMotion())detail.animate?.([{opacity:.55,transform:'translateY(6px)'},{opacity:1,transform:'translateY(0)'}],{duration:200})}document.querySelectorAll('.atlas-course').forEach((button,n)=>{button.classList.toggle('selected',n===i);button.setAttribute('aria-pressed',String(n===i));if(n===i&&scrollStrip){const strip=button.parentElement;strip.scrollTo({left:button.offsetLeft-strip.offsetLeft-8,behavior:atlasMotion()?'smooth':'instant'})}});const position=document.querySelector('#atlas-position');if(position)position.textContent=c.location?'Exploring '+c.name:c.name+' is waiting to be placed.';drawAtlasMarkers();if(c.location&&bookMap)bookMap.panTo([c.location.lat,c.location.lon],{animate:atlasMotion(),duration:.75})};
function stepAtlas(direction){const indices=atlasCourses().map((c,i)=>c.location?i:-1).filter(i=>i>=0);if(!indices.length)return;const current=indices.indexOf(bookSelected),next=current<0?(direction<0?indices.length-1:0):(current+direction+indices.length)%indices.length;selectBookCourse(indices[next],true)}
function surpriseAtlas(){const choices=atlasCourses().map((c,i)=>c.location&&i!==bookSelected?i:-1).filter(i=>i>=0);if(choices.length)selectBookCourse(choices[Math.floor(Math.random()*choices.length)],true)}
fitBookMap=function(){clearAtlasSelection();if(!bookMap)return;const points=atlasCourses().filter(c=>c.location).map(c=>[c.location.lat,c.location.lon]);if(points.length)bookMap.fitBounds(points,{paddingTopLeft:[64,90],paddingBottomRight:[64,70],maxZoom:13,animate:atlasMotion()});else bookMap.setView([22,0],2,{animate:false})};
function toggleAtlasSize(){const stage=document.querySelector('.atlas-stage');if(!stage)return;const expanded=stage.classList.toggle('is-expanded'),button=document.querySelector('#atlas-expand');button.textContent=expanded?'Close map':'Expand map';button.setAttribute('aria-label',expanded?'Close expanded map':'Expand map');button.setAttribute('aria-expanded',String(expanded));stage.setAttribute('role',expanded?'dialog':'region');if(expanded)stage.setAttribute('aria-modal','true');else stage.removeAttribute('aria-modal');requestAnimationFrame(()=>bookMap?.invalidateSize({pan:true,animate:false}))}
window.addEventListener('keydown',e=>{const stage=document.querySelector('.atlas-stage.is-expanded');if(!stage||modal.open)return;if(e.key==='Escape'){toggleAtlasSize();document.querySelector('#atlas-expand')?.focus()}else if(e.key==='Tab'){const items=[...stage.querySelectorAll('button:not([disabled]),a[href],[tabindex="0"]')].filter(el=>el.getClientRects().length),first=items[0],last=items.at(-1);if(!stage.contains(document.activeElement)||e.shiftKey&&document.activeElement===first||!e.shiftKey&&document.activeElement===last){e.preventDefault();(e.shiftKey?last:first)?.focus()}}});
mountBookMap=async function(epoch){const element=document.querySelector('#journey-map');if(!element)return;try{const L=await loadBookMap();if(epoch!==bookEpoch||!element.isConnected||tab!=='Passport'||bookSection!=='map')return;element.innerHTML='';atlasTileFailures=0;bookMap=L.map(element,{scrollWheelZoom:false,worldCopyJump:true,zoomAnimation:atlasMotion(),fadeAnimation:atlasMotion()});const currentMap=bookMap;const tiles=L.tileLayer('https://server.arcgisonline.com/ArcGIS/rest/services/Canvas/World_Light_Gray_Base/MapServer/tile/{z}/{y}/{x}',{maxNativeZoom:16,maxZoom:19,className:'club-map-cartography',attribution:'Tiles © Esri, HERE, Garmin, OpenStreetMap contributors'}).addTo(bookMap);atlasStreet=tiles;atlasImagery=L.tileLayer('https://server.arcgisonline.com/ArcGIS/rest/services/World_Imagery/MapServer/tile/{z}/{y}/{x}',{maxNativeZoom:19,maxZoom:19,attribution:'Imagery © Esri, Maxar, Earthstar Geographics and the GIS User Community'});tiles.on('tileerror',()=>{if(currentMap!==bookMap)return;atlasTileFailures++;const status=document.querySelector('#atlas-map-status');if(status&&atlasTileFailures>=3){status.hidden=false;status.textContent='Some map imagery couldn’t load. Your saved places are still available below.'}});tiles.on('tileload',()=>{if(currentMap!==bookMap)return;atlasTileFailures=0;const status=document.querySelector('#atlas-map-status');if(status)status.hidden=true});atlasMarkers=L.layerGroup().addTo(bookMap);bookMap.on('click',()=>clearAtlasSelection());bookMap.on('zoomend',()=>{syncAtlasImagery();drawAtlasMarkers()});bookMap.on('zoomanim',e=>{document.querySelectorAll('.atlas-frequency-marker').forEach(el=>el.style.setProperty('--badge-size',atlasBadgeSize(e.zoom)+'px'))});element.addEventListener('focusin',()=>currentMap.scrollWheelZoom.enable());element.addEventListener('focusout',e=>{if(!element.contains(e.relatedTarget))currentMap.scrollWheelZoom.disable()});element.addEventListener('pointerdown',()=>element.focus({preventScroll:true}));fitBookMap();syncAtlasImagery();drawAtlasMarkers();L.control.scale({imperial:true,metric:false,position:'bottomleft'}).addTo(bookMap)}catch{if(epoch===bookEpoch&&element.isConnected)element.innerHTML='<div class="map-message">Your places are safe. The map is offline.<p>You can still explore your course collection below.</p><button onclick="render()">Try map again</button></div>'}};
const atlasBaseBook=views.Passport;views.Passport=()=>bookSection==='map'?atlasView():atlasBaseBook();

